#!/usr/bin/env node
/**
 * Scripted terminal demo of the HUD, used for the README animation.
 *
 * It drives the **real extension with the real renderer** over a virtual clock, so every
 * frame below is the genuine widget output and the run is deterministic — no network, no
 * provider, no timing jitter, and it can be regenerated byte-for-byte.
 *
 * The timings are *illustrative, not a benchmark*. They are chosen to exercise the states
 * the HUD can show: connect, prefill, steady streaming, a mid-call stall, and the first
 * call's estimate being corrected to the provider's own count when it finishes. The model
 * name is deliberately neutral for the same reason: attributing synthetic throughput to a
 * real model would read as a benchmark claim, which it is not.
 *
 *   node scripts/demo.mjs braille           # animated, for recording (asciinema/vhs)
 *   node scripts/demo.mjs block
 *   node scripts/demo.mjs compact
 *   node scripts/demo.mjs braille --dump    # a few plain frames, no ANSI, no delays
 *   node scripts/demo.mjs braille --markdown  # the README's static frame, on stdout
 *   DEMO_WIDTH=88 node scripts/demo.mjs compact --source-frame   # the docblock example
 *
 * `--markdown` and `--source-frame` are what keep the docs honest: the two quoted frames
 * are emitted from the same timeline as the GIF rather than typed by hand, so they cannot
 * drift away from what the animation actually shows. scripts/docs-sync.test.mjs asserts
 * both, and fails the build when either is edited without being regenerated.
 *
 * The virtual clock is load-bearing. The HUD measures elapsed time with
 * `performance.now()`, so on a real clock — where the script emits a whole call in a few
 * milliseconds — it would compute latencies a thousand times too small. Overriding the
 * clock keeps the rendered numbers consistent with the timeline being animated.
 */
import { createJiti } from "jiti";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { theme, plain } from "./theme.mjs";

const here = dirname(fileURLToPath(import.meta.url));

/* ------------------------------------------------------------------- options */

const MODES = {
  // The window matches the demo's length rather than sitting at the 120s default: a window
  // several times longer than the session leaves most of the chart empty, which reads as a
  // broken graph instead of an idle one. A little headroom keeps the fill visibly bounded.
  braille: { style: "normal", graphStyle: "braille", tpsWindow: 20 },
  block: { style: "normal", graphStyle: "block", tpsWindow: 20 },
  compact: { style: "compact", graphStyle: "braille", tpsWindow: 20 },
};

const argv = process.argv.slice(2);
const modeName = argv.find((arg) => arg in MODES) ?? "braille";
if (!(modeName in MODES)) {
  console.error(`unknown mode "${modeName}" — expected one of ${Object.keys(MODES).join(", ")}`);
  process.exit(2);
}
const MODE = MODES[modeName];
const DUMP = argv.includes("--dump") || argv.some((arg) => arg.startsWith("--dump="));
const DUMP_ALL = argv.includes("--dump=all");
const MARKDOWN = argv.includes("--markdown");
/** Emit the frame quoted in the source file's header docblock, ` *   `-prefixed. */
const SOURCE_FRAME = argv.includes("--source-frame");
/** Emit the timing plan as JSON, so a test can assert the playback pacing. */
const TIMING = argv.includes("--timing");

/** Render width. Overridable so a documentation comment can quote a narrower frame. */
const widthArg = argv.find((arg) => arg.startsWith("--width="));
const WIDTH = Number(widthArg ? widthArg.slice("--width=".length) : process.env.DEMO_WIDTH ?? 100);
/** Virtual milliseconds per rendered frame. 100ms gives 10 frames per TPS column. */
const FRAME_MS = 100;
/**
 * Real milliseconds to wait per frame. Defaults to FRAME_MS, i.e. the demo plays at real
 * time: one virtual second per real second, which is what a user actually experiences.
 *
 * There used to be a second speed factor downstream (`agg --speed`), and because the two
 * multiplied, the recording ended up ~6x real time. At that rate a single TPS column was
 * drawn in ~25ms and the chart read as a strobing/blinking panel rather than an instrument.
 * Any speed-up belongs in exactly one place — prefer leaving this alone and using
 * `--speed` at encode time, never both.
 */
const REAL_FRAME_MS = Number(process.env.DEMO_FRAME_MS ?? FRAME_MS);
/** Hold the finished HUD so the last frame is readable before the loop restarts. */
const HOLD_MS = 1_500;

/* -------------------------------------------------------------- virtual clock */

let vnow = Date.UTC(2026, 0, 15, 9, 0, 0);
const ORIGIN = vnow;
globalThis.performance = {
  now: () => vnow - ORIGIN,
  timeOrigin: ORIGIN,
  mark: () => {},
  measure: () => {},
  getEntries: () => [],
  clearMarks: () => {},
  clearMeasures: () => {},
};
Date.now = () => vnow;

/* ------------------------------------------------------------------ the calls */

/**
 * Delta sizes in characters per token. The mean is 3.25, close to the ~3.3 measured across
 * real sessions, so the first call's character estimate lands ~19% below the provider's count
 * — which is exactly the correction the HUD makes when the call ends.
 */
const DELTA_LENGTHS = [3, 4, 3, 2, 4, 3, 3, 5, 2, 4, 3, 3];
const deltaFor = (index) => "x".repeat(DELTA_LENGTHS[index % DELTA_LENGTHS.length]);

const CALLS = [
  // Throughput is roughly 1000/itl (decode time is ~tokens x itl), so the inter-token gaps
  // below walk the colour ramp: bright green, plain green, amber, a genuinely slow red, then a
  // recovery. A demo where every second were the same shade would prove nothing about the
  // colouring.
  //
  // Token counts are deliberately modest. Because throughput depends only on `itl`, shrinking
  // the counts keeps the colour bands identical while shortening each call — and the whole
  // animation now plays at real time (see REAL_FRAME_MS), so every virtual second here is a
  // real second of the viewer's attention. A 22s loop is a loop nobody finishes.
  //
  // `costUsd` is a plausible per-call total for an input-heavy session with a small completion
  // (roughly $3/Mtok in, $15/Mtok out — the shape Claude Sonnet produces, and the shape most
  // real sessions in this project have). It is illustrative like everything else here, and it
  // is what makes the HUD's cost readout and the session header total visible in the
  // recording; the extension derives nothing of its own, it only displays the provider's.
  { connect: 140, prefill: 320, tokens: 90, itl: 12, input: 1_240, costUsd: 0.0051 }, //  ~83 tok/s  bright green
  { connect: 90, prefill: 180, tokens: 70, itl: 22, input: 1_380, costUsd: 0.0053 }, //  ~45 tok/s  green
  // Stalls part-way, so the `‖ paused` state is visible.
  { connect: 110, prefill: 260, tokens: 55, itl: 40, input: 1_520, costUsd: 0.0054, stallAfter: 30, stallMs: 900 }, // amber
  { connect: 130, prefill: 420, tokens: 40, itl: 75, input: 1_610, costUsd: 0.0055 }, //  ~13 tok/s  red
  { connect: 80, prefill: 200, tokens: 80, itl: 15, input: 1_740, costUsd: 0.0059 }, //  ~66 tok/s  green
];
const IDLE_AT_START_MS = 700;
/** Pause between calls, so the boundary between writing actions is visible in the chart. */
const BETWEEN_CALLS_MS = 250;

/* ----------------------------------------------------------------------- boot */

const handlers = new Map();
const notifications = [];
let widgetFactory;

const pi = {
  on: (name, fn) => handlers.set(name, fn),
  registerCommand: () => {},
  registerEntryRenderer: () => {},
  appendEntry: () => {},
  getSettings: () => ({ "pi-metrics": MODE }),
  reload: async () => {},
  log: () => {},
};

const ctx = {
  isIdle: () => false,
  hasUI: true,
  mode: "tui",
  ui: {
    notify: (message) => notifications.push(message),
    setStatus: () => {},
    setWidget: (_key, content) => {
      if (typeof content === "function") widgetFactory = content;
    },
  },
};

const jiti = createJiti(import.meta.url, { interopDefault: true });
const factory = (await jiti.import(resolve(here, "../extensions/pi-metrics.ts"))).default;
await factory(pi);
const fire = (name, event) => handlers.get(name)?.(event, ctx);
await fire("session_start", {});

if (!widgetFactory) {
  console.error("the extension did not register a widget — is it enabled?");
  process.exit(1);
}

/* ------------------------------------------------------------- action timeline */

/** @type {{ at: number, run: () => void }[]} */
const actions = [];
let cursor = IDLE_AT_START_MS;

const at = (run) => actions.push({ at: cursor, run });

for (const [callIndex, call] of CALLS.entries()) {
  const message = {
    role: "assistant",
    provider: "demo",
    model: "demo-model",
    api: "openai-completions",
    timestamp: Date.now(),
    content: [],
    stopReason: "stop",
    usage: undefined,
  };
  const asAssistant = () => message;

  at(() => fire("before_provider_request", {}));
  cursor += call.connect;
  at(() => fire("after_provider_response", {}));
  at(() => fire("message_start", { message: asAssistant() }));

  cursor += call.prefill;
  let emitted = 0;
  const emit = () => {
    const delta = deltaFor(emitted);
    emitted += 1;
    message._chars = (message._chars ?? 0) + delta.length;
    fire("message_update", {
      message: asAssistant(),
      assistantMessageEvent: { type: "text_delta", contentIndex: 0, delta, partial: asAssistant() },
    });
  };
  at(emit);

  for (let token = 1; token < call.tokens; token++) {
    cursor += call.itl;
    if (call.stallAfter === token) cursor += call.stallMs;
    at(emit);
  }

  // The provider's own tallies arrive with the finished message.
  cursor += 20;
  at(() => {
    message.usage = {
      input: call.input,
      output: call.tokens,
      cacheRead: 0,
      cacheWrite: 0,
      totalTokens: call.input + call.tokens,
      cost: { input: call.costUsd, output: 0, cacheRead: 0, cacheWrite: 0, total: call.costUsd },
    };
    message.durationMs = call.connect + call.prefill + call.tokens * call.itl + (call.stallMs ?? 0) + 20;
    fire("message_end", { message: asAssistant() });
  });

  cursor += BETWEEN_CALLS_MS;
  void callIndex;
}

const totalVirtualMs = cursor + HOLD_MS;
actions.sort((a, b) => a.at - b.at);

if (TIMING) {
  // Reported rather than asserted here: this file only knows the demo's own pacing. The
  // real-time claim is a property of the *recording* (see record-demo.sh), so the guard test
  // checks both this number and the encoder settings together.
  const frames = Math.floor(totalVirtualMs / FRAME_MS) + 1;
  console.log(
    JSON.stringify(
      {
        mode: modeName,
        width: WIDTH,
        virtualMs: totalVirtualMs,
        frameMs: FRAME_MS,
        realFrameMs: REAL_FRAME_MS,
        frames,
        playbackRealMs: frames * REAL_FRAME_MS,
        speedFactor: totalVirtualMs / (frames * REAL_FRAME_MS),
      },
      null,
      2,
    ),
  );
  process.exit(0);
}

/* -------------------------------------------------------------------- render */

function renderFrame() {
  const widget = widgetFactory({ requestRender: () => {} }, theme);
  return widget.render(WIDTH);
}

/** Repaint in place, the way the live widget does, rather than scrolling. */
function paint(lines) {
  let out = "\x1b[H";
  for (const line of lines) out += `\x1b[2K${line}\r\n`;
  out += "\x1b[0m\x1b[J";
  process.stdout.write(out);
}

const sleep = (ms) => new Promise((done) => setTimeout(done, ms));

if (DUMP || MARKDOWN || SOURCE_FRAME) {
  // A handful of plain frames, for eyeballing and for CI. No ANSI, no waiting.
  const picks = DUMP_ALL || MARKDOWN || SOURCE_FRAME ? null : [0.28, 0.5, 0.68, 0.86, 1];
  const frames = [];
  for (let t = 0; t <= totalVirtualMs; t += FRAME_MS) {
    vnow = ORIGIN + t;
    while (actions.length > 0 && actions[0].at <= t) actions.shift().run();
    frames.push(renderFrame().map(plain));
  }
  const chosen = picks === null ? frames : picks.map((p) => frames[Math.min(frames.length - 1, Math.round((frames.length - 1) * p))]);

  if (SOURCE_FRAME) {
    // The docblock example must be a frame the renderer actually produces. Prefer a
    // finished call with an authoritative count, and avoid any frame that happens to be
    // truncated — an example littered with `…` reads as a broken HUD rather than a
    // representative one. Regenerate, never hand-edit: scripts/docs-sync.test.mjs asserts
    // the source file contains this output verbatim.
    const score = (lines) => {
      const text = lines.join("\n");
      let points = 0;
      if (/\(usage\)/.test(text)) points += 6;
      const calls = /(\d+) calls/.exec(text);
      if (calls) points += Math.min(5, Number(calls[1]));
      // A truncation marker anywhere means the frame is mid-flight in an ugly way.
      if (text.includes("…")) points -= 20;
      if (/waiting \d/.test(text)) points += 1;
      return points;
    };
    let best = chosen[0];
    let bestScore = -Infinity;
    for (const lines of chosen) {
      const points = score(lines);
      if (points > bestScore) {
        bestScore = points;
        best = lines;
      }
    }
    // Two spaces after `*`, so the render's own single-space indent lands at the same
    // column the surrounding docblock uses.
    for (const line of best) console.log(` *  ${line.replace(/\s+$/, "")}`);
    process.exit(0);
  }

  if (MARKDOWN) {
    // Pick the frame that best shows the states worth advertising: a finished session with a
    // stalled call, so `‖ paused` and `waiting …` both appear. Deterministic, so re-running
    // this produces the identical block and the README can be regenerated, not re-typed.
    const score = (lines) => {
      const text = lines.join("\n");
      let points = 0;
      if (/waiting \d/.test(text)) points += 4;
      if (/\(usage\)/.test(text)) points += 2;
      const calls = /(\d+) calls/.exec(text);
      if (calls) points += Math.min(3, Number(calls[1]));
      return points;
    };
    let best = chosen[0];
    let bestScore = -1;
    for (const lines of chosen) {
      const points = score(lines);
      if (points >= bestScore) {
        bestScore = points;
        best = lines;
      }
    }
    const width = Math.max(...best.filter((l) => l.trim()).map((l) => l.length));
    console.log("```");
    for (const line of best) console.log(line.replace(/\s+$/, "").slice(0, width).replace(/\s+$/, ""));
    console.log("```");
    process.exit(0);
  }

  chosen.forEach((lines, index) => {
    console.log(`\n───── frame ${index + 1}/${chosen.length} (${modeName}) ${"─".repeat(40)}`);
    console.log(lines.join("\n"));
  });
  process.exit(0);
}

process.stdout.write("\x1b[2J\x1b[?25l");
const restore = () => {
  process.stdout.write("\x1b[?25h\x1b[0m\n");
  process.exit(0);
};
process.on("SIGINT", restore);

for (let t = 0; t <= totalVirtualMs; t += FRAME_MS) {
  vnow = ORIGIN + t;
  while (actions.length > 0 && actions[0].at <= t) actions.shift().run();
  paint(renderFrame());
  await sleep(REAL_FRAME_MS);
}

restore();
